// regra — plano §5 W11: controle no formato do PNCP, de 1 a 20 por pedido (o site já limita; aqui é a 2ª cerca)
const b = $input.first().json.body || {};
const re = /^\d{14}-\d+-\d+\/\d{4}$/;
const lista = Array.isArray(b.controles) ? [...new Set(b.controles.map(String))] : [];
const ruins = lista.filter(c => !re.test(c));
if (!lista.length || lista.length > 20 || ruins.length) {
  return [{ json: { valido: false, detail: !lista.length ? 'informe de 1 a 20 controles'
    : lista.length > 20 ? 'no máximo 20 controles por pedido' : 'controle fora do formato do PNCP: ' + ruins.join(', ') } }];
}
return lista.map(c => ({ json: { valido: true, controle: c, forcar: b.forcar === true,
  solicitado_por: String(b.solicitado_por || 'site') } }));

// regra — o payload da fn_registrar_vista (db/020), com os nomes da API de consulta do PNCP.
// atualizado_pncp vai VAZIO de propósito: o W01 compara o carimbo da BUSCA (data_atualizacao_pncp),
// que não é o mesmo campo desta API; gravar este daria 'retificada' falsa na próxima rodada.
// regra — 429/5xx/rede NÃO é 'não achada' (scripts/fopa/pncp.py:62-101): o 429 do PNCP vem em HTML e pede
// 30 s, mais do que o site espera (15 s); a compra fica recusada com 'PNCP indisponível, tente de novo'.
const pedidos = $('Validar pedido').all().map(i => i.json);
return $input.all().map((it, i) => {
  const p = pedidos[i];
  const r = it.json || {};
  const d = (r.statusCode === 200 && r.body && typeof r.body === 'object') ? r.body : null;
  const pncp_falha = r.error ? 'sem resposta (' + String(r.error.message || r.error.code || 'rede').slice(0, 80) + ')'
    : (r.statusCode === 429 || r.statusCode >= 500 || r.statusCode == null) ? 'HTTP ' + r.statusCode : '';
  const [cnpjSeqAno, ano] = p.controle.split('/');
  const seq = Number(cnpjSeqAno.split('-')[2]);
  const payload = d ? {
    ano: Number(ano), seq, orgao: (d.orgaoEntidade || {}).razaoSocial || null,
    uf: (d.unidadeOrgao || {}).ufSigla || null, municipio: (d.unidadeOrgao || {}).municipioNome || null,
    modalidade: d.modalidadeNome || null, objeto: String(d.objetoCompra || '').slice(0, 1200),
    situacao: d.situacaoCompraNome || null, publicado_em: d.dataPublicacaoPncp || null,
    fim_prazo: d.dataEncerramentoProposta || null,
    link: 'https://pncp.gov.br/app/editais/' + p.controle.slice(0, 14) + '/' + ano + '/' + seq } : null;
  return { json: { ...p, achou: !!d, http: r.statusCode ?? null, pncp_falha, payload,
                   objeto: payload ? payload.objeto : '' } };
});

// Um item com o resumo (para a resposta e para o W10) e a lista das reservadas com forcar (para o W20 direto).
const itens = $input.all().map(i => i.json);
const aceitos = itens.filter(i => i.aceito).map(i => i.controle);
const desconhecida = (i) => i.achou_no_pncp ? 'fora do recorte de 2026 (ADR-015)'
  : i.pncp_falha ? 'PNCP indisponível agora (' + i.pncp_falha + '): tente de novo em instantes'
  : 'não achada no PNCP';
const recusados = itens.filter(i => !i.aceito).map(i => i.controle + ': ' + (i.motivo === 'desconhecida'
  ? desconhecida(i) : i.motivo));
const reservadas = itens.filter(i => i.aceito && i.reservada && i.forcar).map(i => i.controle);
const paraFila = aceitos.filter(c => !reservadas.includes(c));
return [{ json: { aceitos, recusados, reservadas, para_fila: paraFila.length } }];

// O pedido e a hora em que chegou: a linha única do fim (execucoes_workflow) leva a duração.
const b = $input.first().json.body || {};
return [{ json: { controle: String(b.controle ?? '').trim(), solicitado_por: String(b.solicitado_por || 'site'),
  inicio: $now.toUTC().toISO() } }];

// regra — o W30 "Registrar resultado" para UMA licitação: voltou do W24 (republicada ou recusada), 409 sem nada
// a republicar (pulada: já está nas regras atuais), /reverificar falhou (404 sem vigente, 409 sem leitura, worker
// fora), ou o W24 caiu. Vira UMA linha em execucoes_workflow; custo R$ 0 (sem modelo, sem OCR: ADR-011).
const p = $('Pedido (reverificar)').first().json;
const rv = $('POST /reverificar no worker').first().json || {};
const j = $input.first().json || {};
const rodou = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const retomada = rodou('Verificação já gravada');
const texto = (b) => (b && typeof b === 'object') ? String(b.detail ?? JSON.stringify(b)) : String(b ?? '');
// bigint chega como TEXTO do nó Postgres do W24: id vira número (o site e os outros fluxos gravam número)
const num = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v))) ? null : Number(v);
let r;
if (rodou('Republicar (W24)') && j.modo !== undefined && j.ok !== undefined) {         // voltou do W24
  const mudaram = Object.keys((j.diff && j.diff.vereditos) || {});
  r = { ok: j.ok === true, republicada: j.ok === true, retomada, estado: j.estado ?? null, mudaram,
        antes_verificacao_id: num(j.antes_verificacao_id), verificacao_id: num(j.verificacao_id),
        email_id: num(j.email_id), motivo: j.motivo ?? null };
} else if (rodou('Republicar (W24)')) {                                              // o W24 caiu
  r = { ok: false, retomada, motivo: 'W24 republicar falhou: '
        + String((j.error && (j.error.message || j.error.description)) || JSON.stringify(j)).slice(0, 300) };
} else if (retomada && !($('GET /versao (retomada)').first().json || {}).versao_regras) {  // sem a versão, sem retomada
  const g = $('GET /versao (retomada)').first().json || {};
  r = { ok: false, retomada, motivo: 'worker /versao sem resposta: '
        + String((g.error && (g.error.message || g.error.code)) || JSON.stringify(g)).slice(0, 240) };
} else if (retomada) {                                                               // 409 e nada pendente
  r = { ok: true, pulada: true, retomada, motivo: 'já verificada nesta versão das regras e sem verificação '
        + 'pendente de republicar' };
} else {                                                                             // /reverificar falhou
  r = { ok: false, retomada, motivo: rv.error
        ? 'worker sem resposta: ' + String(rv.error.message || rv.error.code || JSON.stringify(rv.error)).slice(0, 240)
        : `/reverificar HTTP ${rv.statusCode}: ` + texto(rv.body).slice(0, 400) };
}
const nova = (rv.statusCode === 200 && rv.body) ? rv.body : null;
return [{ json: {
  status: r.ok ? 'ok' : 'erro', erro: r.ok ? null : r.motivo, inicio: p.inicio, controle: p.controle,
  argumentos: { acao: 'reverificar', controle: p.controle, solicitado_por: p.solicitado_por },
  // números que o site mostra em /execucoes (ids ficam de fora pela terminação _id)
  contadores: { republicadas: r.republicada ? 1 : 0, vereditos_mudados: (r.mudaram || []).length,
    puladas: r.pulada ? 1 : 0, falhas: r.ok ? 0 : 1, retomada: r.retomada === true,
    reverificacao_http: rv.statusCode ?? null, versao_regras: nova ? nova.versao_regras : null,
    base_verificacao_id: nova ? num(nova.base_verificacao_id) : null,
    antes_verificacao_id: r.antes_verificacao_id ?? null, verificacao_id: r.verificacao_id ?? null,
    email_id: r.email_id ?? null, estado: r.estado ?? null, mudaram: r.mudaram || [], motivo: r.motivo ?? null },
} }];

// regra — o site já conferiu controle e 17 respostas (api/site.py ImportarRespostasIn); aqui é a 2ª cerca.
// A validação de CADA resposta (ids Q1-Q17, página inteira, confiança) é do worker: api/extracao.py validar_respostas.
const b = $input.first().json.body || {};
const controle = String(b.controle ?? '').trim();
const respostas = Array.isArray(b.respostas) ? b.respostas : null;
const pr = (b.procedencia && typeof b.procedencia === 'object') ? b.procedencia : {};
const detail = !/^[0-9]{14}-[0-9]+-[0-9]+[/][0-9]{4}$/.test(controle) ? 'controle fora do formato do PNCP: ' + controle
  : (!respostas || respostas.length !== 17) ? 'informe as 17 respostas (vieram ' + (respostas ? respostas.length : 0) + ')'
  : null;
return [{ json: { valido: !detail, detail, controle, respostas: respostas || [],
  procedencia: { provedor: String(pr.provedor || 'claude-code'), modelo: pr.modelo ? String(pr.modelo) : null,
                 sessao: pr.sessao ? String(pr.sessao) : null },
  solicitado_por: String(b.solicitado_por || 'site'), inicio: $now.toUTC().toISO() } }];

// regra — toda importação aceita vira UMA linha em execucoes_workflow (o site já recebeu o 202): publicada ou
// republicada pelo W24, ou por que não (lease de outro fluxo, W24 recusou ou caiu). Custo de API R$ 0: o agente
// não passa pelo modelo pago (ADR-014); o que ele custou fora daqui não é medido (ADR-012: não é 'grátis').
const p = $('Pedido (importar)').first().json;
const e = $('Estado para importar').first().json;
const w = ($('POST /importar-respostas no worker').first().json || {}).body || {};
const j = $input.first().json || {};
const rodou = (n) => { try { return $(n).isExecuted; } catch (x) { return false; } };
// bigint chega como TEXTO dos nós Postgres: id vira número (o site e os outros fluxos gravam número)
const num = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v))) ? null : Number(v);
const pelo24 = rodou('Publicar a importada (W24)') || rodou('Republicar a importada (W24)');
let r;
if (pelo24 && j.ok !== undefined) {                                   // voltou do W24
  r = { ok: j.ok === true, estado: j.estado ?? null, verificacao_id: num(j.verificacao_id),
        email_id: num(j.email_id), mudaram: Object.keys((j.diff && j.diff.vereditos) || {}), motivo: j.motivo ?? null,
        ancoradas: j.resumo ? num(j.resumo.ancoradas) : null, respondidas: j.resumo ? num(j.resumo.respondidas) : null };
} else if (pelo24) {                                                  // o W24 caiu
  r = { ok: false, motivo: 'W24 ' + e.modo + ' falhou: '
        + String((j.error && (j.error.message || j.error.description)) || JSON.stringify(j)).slice(0, 300) };
} else {                                                              // o lease não veio
  r = { ok: false, motivo: 'a licitação foi pega por outro fluxo entre a leitura do estado e a importação; '
        + 'a execução ' + w.execucao_id + ' ficou em curso, sem verificação' };
}
return [{ json: {
  status: r.ok ? 'ok' : 'erro', erro: r.ok ? null : r.motivo, inicio: p.inicio, controle: p.controle,
  argumentos: { acao: 'importar-respostas', controle: p.controle, solicitado_por: p.solicitado_por,
                procedencia: p.procedencia, modo: e.modo },
  // números que o site mostra em /execucoes (ids ficam de fora pela terminação _id)
  contadores: { importadas: 1, publicadas: (r.ok && e.modo === 'publicar') ? 1 : 0,
    republicadas: (r.ok && e.modo === 'republicar') ? 1 : 0, falhas: r.ok ? 0 : 1,
    vereditos_mudados: (r.mudaram || []).length, mudaram: r.mudaram || [],
    ancoradas: r.ancoradas ?? null, respondidas: r.respondidas ?? null, estado_antes: e.estado,
    estado: r.estado ?? null, execucao_id: num(w.execucao_id), verificacao_id: r.verificacao_id ?? num(w.verificacao_id),
    email_id: r.email_id ?? null, motivo: r.motivo ?? null },
} }];
